func pkNameMsg(msg *strings.Builder, why int32, b []byte, from int32, to int32) int32 {
	// `unknown engine: "foo"`: the reason's sentence and the name as given (printable ASCII only, cut at 64 bytes).
	PkerrEmitName(msg, why)
	port.TextAscii(msg, ": ")
	port.TextCp(msg, 34)
	var i int32 = from
	var c int32 = 0
	for (i < to) && ((i - from) < 64) {
		c = port.BlobU8(b, i)
		if (c < 32) || (c > 126) {
			c = 63
		}
		port.TextCp(msg, c)
		i += 1
	}
	port.TextCp(msg, 34)
	return why
}

func PkParseEngines(b []byte, from int32, to int32, out *port.Cells, msg *strings.Builder) int32 {
	// Read a comma-separated list of engine names (`tesseract,ppocr`, spaces around a name allowed; an option's value) and push their ids to `out`. 0, or `pkerr-unknown-engine` with the name in `msg`.
	var s int32 = from
	var i int32 = from
	var c int32 = 44
	var a int32 = 0
	var z int32 = 0
	var code int32 = 0
	for i <= to {
		c = 44
		if i < to {
			c = port.BlobU8(b, i)
		}
		if c == 44 {
			a = s
			z = i
			for (a < z) && (port.BlobU8(b, a) == 32) {
				a += 1
			}
			for (a < z) && (port.BlobU8(b, z-1) == 32) {
				z -= 1
			}
			if z > a {
				code = EngFind(b, a, z)
				if code < 0 {
					return pkNameMsg(msg, PkerrUnknownEngine(), b, a, z)
				}
				port.CellsPush(out, code)
			}
			s = i + 1
		}
		i += 1
	}
	return 0
}

