func PkExplain(code int32, subject *port.Cells, msg *strings.Builder) int32 {
	// The sentence of a refusal of `pk-resolve` or `pk-record-engines`: the reason, then its subject (`subject` is what the call left in `out`).
	PkerrEmitName(msg, code)
	if code == PkerrUnknownEngine() {
		port.TextAscii(msg, ": ")
		port.TextI32(msg, port.CellsAt(subject, 0))
	}
	if code == PkerrUnknownPack() {
		port.TextAscii(msg, ": ")
		port.TextI32(msg, port.CellsAt(subject, 0))
	}
	if code == PkerrUnknownClass() {
		port.TextAscii(msg, ": ")
		port.TextI32(msg, port.CellsAt(subject, 0))
	}
	if code == PkerrBadLanguage() {
		port.TextAscii(msg, ": ")
		port.TextI32(msg, port.CellsAt(subject, 0))
	}
	if (code == PkerrNotOcr()) || (code == PkerrEngineClass()) {
		port.TextAscii(msg, ": ")
		port.TextCp(msg, 34)
		EngEmitName(msg, port.CellsAt(subject, 0))
		port.TextCp(msg, 34)
	}
	if code == PkerrEngineClass() {
		port.TextAscii(msg, " on ")
		port.TextCp(msg, 34)
		PclsEmitName(msg, port.CellsAt(subject, 1))
		port.TextCp(msg, 34)
	}
	return code
}

func pkMark(c *port.Cells, at int32, v int32) int32 {
	// Mark a pack of the resolution's scratch: 1 needed, 2 conditional (the fallback partner's), which a needed mark is never lowered to.
	if v == 1 {
		port.CellsSet(c, at, 1)
	} else if port.CellsAt(c, at) == 0 {
		port.CellsSet(c, at, 2)
	}
	return 0
}

func pkHas(c *port.Cells, from int32, v int32) int32 {
	// 1 when `v` is among the cells of `c` from `from` on.
	var n int32 = port.CellsLen(c)
	var i int32 = from
	for i < n {
		if port.CellsAt(c, i) == v {
			return 1
		}
		i += 1
	}
	return 0
}

func pkLangAdd(c *port.Cells, base int32, lang int32) int32 {
	// Insert the language into the sorted, duplicate-free list that starts at `base` of `c`.
	var i int32 = base
	var n int32 = port.CellsLen(c)
	var at int32 = -1
	var v int32 = 0
	var prev int32 = 0
	for (i < n) && (at < 0) {
		v = port.CellsAt(c, i)
		if v == lang {
			return 0
		}
		if v > lang {
			at = i
		}
		i += 1
	}
	if at < 0 {
		port.CellsPush(c, lang)
		return 0
	}
	port.CellsPush(c, 0)
	i = port.CellsLen(c) - 1
	for i > at {
		prev = port.CellsAt(c, i-1)
		port.CellsSet(c, i, prev)
		i -= 1
	}
	port.CellsSet(c, at, lang)
	return 0
}

func pkFail(out *port.Cells, code int32, a int32, b int32) int32 {
	// Refuse: `out` holds the subject (what `pk-explain` writes) and the reason is the answer.
	port.CellsDrop(out, 0)
	port.CellsPush(out, a)
	port.CellsPush(out, b)
	return code
}

func PkResolve(pclass int32, flags int32, langs *port.Cells, engines *port.Cells, installed *port.Cells, out *port.Cells, scratch *port.Cells) int32 {
	// D896's `prepare()`, as kin policy: the packs a conversion needs and which of them are missing.
	// pclass: the platform class (`pcls`). flags: `pkf-osd` when orientation and script detection are wanted. langs: packed ISO 639-3 cells; none means English.
	// engines: the engines asked for (`eng`); none means the class's turnkey default. installed: the codes (`pkid`) of the packs present.
	// out: rows `[state engine pack lang]` (`pstate`). The packs needed, in the catalogue's order, `installed` or `missing`; then the (engine, language) pairs no pack of the
	// catalogue reads, `unsupported` (pack 0), sorted by engine then language. The order does not depend on the order or repetition of the inputs.
	// On a refusal the answer is the reason (`pkerr`) and `out` holds `[subject-a subject-b]` for `pk-explain`. scratch: working cells.
	port.CellsDrop(out, 0)
	port.CellsDrop(scratch, 0)
	if PkClassKnown(pclass) == 0 {
		return pkFail(out, PkerrUnknownClass(), pclass, 0)
	}
	var np int32 = 24
	var ne int32 = 8
	var sel int32 = np + 1
	var lb int32 = (np + 1) + ne
	var i int32 = 0
	var r int32 = 0
	var v int32 = 0
	var eng int32 = 0
	var p int32 = 0
	var pe int32 = 0
	var needs int32 = 0
	var pk int32 = 0
	var lang int32 = 0
	var j int32 = 0
	var sv int32 = 0
	var want int32 = 0
	for i < lb {
		port.CellsPush(scratch, 0)
		i += 1
	}
	if port.CellsLen(engines) == 0 {
		r = pkEnRow(PkDefaultEngine(pclass))
		if r >= 0 {
			port.CellsSet(scratch, sel+r, 1)
		}
	} else {
		i = 0
		for i < port.CellsLen(engines) {
			eng = port.CellsAt(engines, i)
			r = pkEnRow(eng)
			if r < 0 {
				return pkFail(out, PkerrUnknownEngine(), eng, 0)
			}
			if EnTable[r*8+2] != EkindOcr() {
				return pkFail(out, PkerrNotOcr(), eng, 0)
			}
			if PkEngineOn(eng, pclass) == 0 {
				return pkFail(out, PkerrEngineClass(), eng, pclass)
			}
			port.CellsSet(scratch, sel+r, 1)
			i += 1
		}
	}
	if port.CellsAt(scratch, sel+pkEnRow(EngAppleVision())) == 1 {
		eng = PkFallbackEngine(pclass)
		r = pkEnRow(eng)
		if (r >= 0) && (port.CellsAt(scratch, sel+r) == 0) {
			port.CellsSet(scratch, sel+r, 2)
		}
	}
	if port.CellsLen(langs) == 0 {
		port.CellsPush(scratch, PkLangEng())
	} else {
		i = 0
		for i < port.CellsLen(langs) {
			lang = port.CellsAt(langs, i)
			if lang <= 0 {
				return pkFail(out, PkerrBadLanguage(), lang, 0)
			}
			pkLangAdd(scratch, lb, lang)
			i += 1
		}
	}
	i = 0
	for i < port.CellsLen(installed) {
		p = port.CellsAt(installed, i)
		if PkPackKnown(p) == 0 {
			return pkFail(out, PkerrUnknownPack(), p, 0)
		}
		i += 1
	}
	r = 0
	for r < ne {
		sv = port.CellsAt(scratch, sel+r)
		if sv > 0 {
			eng = EnTable[r*8+0]
			needs = EnTable[r*8+7]
			p = 1
			for p <= np {
				pe = PkPackEngine(p)
				pk = PkPackKind(p)
				if ((pe == pkPackOwner(eng)) || (pe == 0)) && ((needs & pk) != 0) {
					if pk == PkindOsd() {
						if (flags & PkfOsd()) != 0 {
							pkMark(scratch, p, sv)
						}
					}
					if (pk == PkindDetector()) || (pk == PkindClassifier()) {
						pkMark(scratch, p, sv)
					}
				}
				p += 1
			}
			j = lb
			for j < port.CellsLen(scratch) {
				lang = port.CellsAt(scratch, j)
				want = sv
				if sv == 2 {
					if ocrloc.OlHas(PkEngineOen(EngAppleVision()), lang) == 0 {
						want = 1
					}
				}
				p = PkPackFor(eng, PkindRecognizer(), lang)
				if (p != 0) && ((needs & PkindRecognizer()) != 0) {
					pkMark(scratch, p, want)
				}
				p = PkPackFor(eng, PkindLexicon(), lang)
				if (p != 0) && ((needs & PkindLexicon()) != 0) {
					pkMark(scratch, p, want)
				}
				j += 1
			}
		}
		r += 1
	}
	port.CellsDrop(out, 0)
	p = 1
	for p <= np {
		if port.CellsAt(scratch, p) > 0 {
			v = PstateMissing()
			if port.CellsAt(scratch, p) == 2 {
				v = PstateConditional()
			}
			if pkHas(installed, 0, p) == 1 {
				v = PstateInstalled()
			}
			port.CellsPush(out, v)
			port.CellsPush(out, PkPackEngine(p))
			port.CellsPush(out, p)
			port.CellsPush(out, 0)
		}
		p += 1
	}
	r = 0
	for r < ne {
		sv = port.CellsAt(scratch, sel+r)
		if (sv > 0) && ((EnTable[r*8+7] & PkindRecognizer()) != 0) {
			eng = EnTable[r*8+0]
			j = lb
			for j < port.CellsLen(scratch) {
				lang = port.CellsAt(scratch, j)
				want = sv
				if sv == 2 {
					if ocrloc.OlHas(PkEngineOen(EngAppleVision()), lang) == 0 {
						want = 1
					}
				}
				if (want == 1) && (PkPackFor(eng, PkindRecognizer(), lang) == 0) {
					port.CellsPush(out, PstateUnsupported())
					port.CellsPush(out, eng)
					port.CellsPush(out, 0)
					port.CellsPush(out, lang)
				}
				j += 1
			}
		}
		r += 1
	}
	return 0
}

func PkRows(out *port.Cells) int32 {
	// How many rows `pk-resolve` left in `out`.
	return port.CellsLen(out) / 4
}

func PkRowState(out *port.Cells, row int32) int32 {
	return port.CellsAt(out, row*4)
}

func PkRowEngine(out *port.Cells, row int32) int32 {
	return port.CellsAt(out, (row*4)+1)
}

func PkRowPack(out *port.Cells, row int32) int32 {
	return port.CellsAt(out, (row*4)+2)
}

func PkRowLang(out *port.Cells, row int32) int32 {
	return port.CellsAt(out, (row*4)+3)
}

func PkMissing(out *port.Cells) int32 {
	// How many packs of the resolution are missing.
	var i int32 = 0
	var n int32 = 0
	for i < PkRows(out) {
		if PkRowState(out, i) == PstateMissing() {
			n += 1
		}
		i += 1
	}
	return n
}

func PkRecordEngines(out *port.Cells, pclass int32, avail *port.Cells) int32 {
	// The engine table of a conversion, for a transcript's `:pk-engines`: one `[eng caps role]` row for each engine of `avail` (engine ids, any order, repeats allowed),
	// in the table's order. `caps` is the ceiling the table declares and `role` the default role on the class. 0, or the reason (`pkerr`) with the subject left in `out`.
	port.CellsDrop(out, 0)
	if PkClassKnown(pclass) == 0 {
		return pkFail(out, PkerrUnknownClass(), pclass, 0)
	}
	var i int32 = 0
	var eng int32 = 0
	for i < port.CellsLen(avail) {
		eng = port.CellsAt(avail, i)
		if PkEngineKnown(eng) == 0 {
			return pkFail(out, PkerrUnknownEngine(), eng, 0)
		}
		if PkEngineOn(eng, pclass) == 0 {
			return pkFail(out, PkerrEngineClass(), eng, pclass)
		}
		i += 1
	}
	var r int32 = 0
	var rowEng int32 = 0
	var role int32 = 0
	for r < 8 {
		rowEng = EnTable[r*8+0]
		if pkHas(avail, 0, rowEng) == 1 {
			role = PkRoleDefault(rowEng, pclass)
			port.CellsPush(out, rowEng)
			port.CellsPush(out, EnTable[r*8+4])
			port.CellsPush(out, role)
		}
		r += 1
	}
	return 0
}
